/// Java `InsecurePlayerOptions`.
#[derive(Debug, Clone, PartialEq)]
pub struct InsecurePlayerOptions {
    /// `uuid`.
    pub uuid: Uuid,
    /// `username`.
    pub username: String,
    /// `skin`.
    pub skin: Option<PlayerSkin>,
}

impl Default for InsecurePlayerOptions {
    fn default() -> Self {
        Self {
            uuid: Uuid::default(),
            username: String::new(),
            skin: None,
        }
    }
}

impl Wire for InsecurePlayerOptions {
    fn encode(&self, writer: &mut Writer) -> Result<()> {
        let mut fixed = vec![0u8; 25usize];
        let mut bits = NullableBitset::new(1usize);
        if self.skin.is_some() {
            bits.set(0, true)?;
        }
        fixed[..bits.as_bytes().len()].copy_from_slice(bits.as_bytes());
        let mut vars = Writer::new();
        write_uuid_at(&mut fixed, 1, self.uuid)?;
        write_i32_at(&mut fixed, 17, vars.len() as i32)?;
        vars.write_var_ascii_string("username", self.username.as_str(), 16usize)?;
        if let Some(value) = &self.skin {
            write_i32_at(&mut fixed, 21, vars.len() as i32)?;
            value.encode(&mut vars)?;
        } else {
            write_i32_at(&mut fixed, 21, -1)?;
        }
        writer.write_slice(&fixed);
        writer.write_slice(vars.as_slice());
        Ok(())
    }

    fn decode(reader: &mut Reader<'_>) -> Result<Self> {
        let fixed = reader.read_slice(25usize)?.to_vec();
        let bits = NullableBitset::from_bytes(fixed[..1usize].to_vec());
        let var_start = reader.position();
        Ok(Self {
            uuid: read_at(&fixed, 1, |reader| reader.read_uuid())?,
            username: {
                let expected = (reader.position() - var_start) as i32;
                let found = read_at(&fixed, 17, |reader| reader.read_i32())?;
                if found != expected {
                    return Err(crate::io::ProtocolError::NonCanonicalOffset {
                        field: "username",
                        found,
                        expected,
                    });
                }
                reader.read_var_ascii_string("username", 16usize)?
            },
            skin: {
                if bits.is_set(0)? {
                    let expected = (reader.position() - var_start) as i32;
                    let found = read_at(&fixed, 21, |reader| reader.read_i32())?;
                    if found != expected {
                        return Err(crate::io::ProtocolError::NonCanonicalOffset {
                            field: "skin",
                            found,
                            expected,
                        });
                    }
                    let value = PlayerSkin::decode(reader)?;
                    Some(value)
                } else {
                    let found = read_at(&fixed, 21, |reader| reader.read_i32())?;
                    if found != -1 {
                        return Err(crate::io::ProtocolError::NonCanonicalOffset {
                            field: "skin",
                            found,
                            expected: -1,
                        });
                    }
                    None
                }
            },
        })
    }
}

